const OURS940_SHA: &str = "16a6195ebf472b9d328c9da1f6267a400d3f34c783e39080641e8714219f7caf";
const ORIGINAL940_SHA: &str = "7fe239c8c7c5afe12db2c3125286b45cf8b168cac45a408d0c443cc4ecfe5427";
